import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"疑難排解","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/troubleshooting.md","filePath":"zh-TW/guide/troubleshooting.md","lastUpdated":1793173149000}`),a={name:`zh-TW/guide/troubleshooting.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="疑難排解" tabindex="-1">疑難排解 <a class="header-anchor" href="#疑難排解" aria-label="Permalink to “疑難排解”">​</a></h1><p>本頁彙整常見問題與解決方式。</p><h2 id="應用程式無法啟動或一開啟就閃退" tabindex="-1">應用程式無法啟動或一開啟就閃退 <a class="header-anchor" href="#應用程式無法啟動或一開啟就閃退" aria-label="Permalink to “應用程式無法啟動或一開啟就閃退”">​</a></h2><p>症狀：Sudoku 打不開、一開啟就閃退，或出現非預期的錯誤。</p><p>可嘗試的步驟：</p><ol><li>確認裝置符合最低系統需求（iOS/iPadOS 16+、macOS 15+）。</li><li>強制結束 App 後重新啟動。</li><li>重新啟動裝置。</li><li>從 App Store 重新安裝 App。</li><li>若問題仍未解決，請在專案儲存庫提出 issue 並附上詳細資訊。</li></ol><h2 id="效能問題" tabindex="-1">效能問題 <a class="header-anchor" href="#效能問題" aria-label="Permalink to “效能問題”">​</a></h2><p>如果遊戲卡頓或反應遲緩：</p><ol><li>關閉其他耗資源的應用程式。</li><li>在 Mac 上，用「活動監視器」檢查是否有 CPU 使用率過高的情況。</li><li>在較舊的裝置上，可嘗試較簡單的難度（簡單或中等）。</li></ol><h2 id="icloud-同步沒有作用" tabindex="-1">iCloud 同步沒有作用 <a class="header-anchor" href="#icloud-同步沒有作用" aria-label="Permalink to “iCloud 同步沒有作用”">​</a></h2><p>如果進度沒有在裝置間同步：</p><ol><li>確認所有裝置都登入同一個 Apple ID。</li><li>確認已在「系統設定」（Mac）或「設定」（iOS/iPadOS）中啟用 iCloud 雲碟。</li><li>確認網路連線正常。</li><li>在「設定」→［你的名字］→ iCloud →「使用 iCloud 的 App」中，將 Sudoku 的 iCloud 關閉後再重新開啟。</li><li>重新啟動所有裝置後再試一次。</li></ol><h2 id="game-center-無法連線" tabindex="-1">Game Center 無法連線 <a class="header-anchor" href="#game-center-無法連線" aria-label="Permalink to “Game Center 無法連線”">​</a></h2><p>如果 Game Center 的成就或排行榜沒有更新：</p><ol><li>確認已登入 Game Center（iOS 為「設定」→「Game Center」；Mac 為「系統設定」）。</li><li>檢查網路連線。</li><li>登出 Game Center 後再重新登入。</li></ol><h2 id="檢視日誌" tabindex="-1">檢視日誌 <a class="header-anchor" href="#檢視日誌" aria-label="Permalink to “檢視日誌”">​</a></h2><p>排查閃退問題時，應用程式日誌會很有幫助。在 Mac 的沙箱（App Store）版本中，請查看：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~/Library/Containers/com.w3cub.sudoku/Data/Library/Logs/sudoku/sudoku.log</span></span></code></pre></div><p>在 iOS/iPadOS 上，請將裝置連接到 Mac，並使用 Console.app 檢視日誌，以「Sudoku」作為篩選條件。</p><h2 id="重設-app" tabindex="-1">重設 App <a class="header-anchor" href="#重設-app" aria-label="Permalink to “重設 App”">​</a></h2><p>若要重設設定並清除本機資料（Mac）：</p><ol><li>結束 Sudoku</li><li>移除容器（請小心——這會刪除所有設定、統計資料與遊戲存檔）：</li></ol><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.sudoku</span></span></code></pre></div><ol start="3"><li>重新開啟 Sudoku 並重新設定。</li></ol><p>在 iPhone/iPad 上，刪除並重新安裝 App 即可重設所有資料。</p><p><strong>注意</strong>：如果你使用 iCloud 同步，在某一台裝置上重設後，重新啟動時可能會再次從 iCloud 下載資料。若要在所有裝置上徹底重設，可能需要每台裝置都各自重設一次。</p><h2 id="回報問題" tabindex="-1">回報問題 <a class="header-anchor" href="#回報問題" aria-label="Permalink to “回報問題”">​</a></h2><p>提出 issue 時，請附上：</p><ul><li>裝置類型（iPhone、iPad 或 Mac）</li><li>作業系統版本（設定 → 一般 → 關於本機）</li><li>Sudoku 版本（設定 → 關於）</li><li>重現步驟</li><li>日誌或截圖（若有）</li></ul><p>這些資訊能幫助維護人員更快找出並修正問題。</p>`,30)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};